
import type { MoneyValueInput } from './MoneyValueInput.js';

export type ModifierInput = { /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "default_quantity"?: string; /** Flint line-item tax category. */ "line_item_tax_category"?: "general" | "physical_goods" | "digital_goods" | "software" | "saas" | "services" | "professional_services" | "food" | "prepared_food" | "clothing" | "medical_goods" | "admission"; "metadata"?: Record<string, string>; "modifier_group_id"?: never; "modifier_id"?: never; "name": string; /** Format: int32. */ "position": number; "selected_by_default": boolean; "show_on_fulfillment": boolean; "show_on_receipt": boolean; "status": "active" | "inactive" | "archived"; "taxable"?: boolean; "unit_price_delta_money"?: MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; };
